def load_routes():
    routes = {0: list(_PAYLOAD['base'])}
    for rid, patch in _PAYLOAD['patches'].items():
        tape = list(routes[0])
        for step, action in patch:
            tape[int(step)] = action
        routes[int(rid)] = tape
    return routes
